(function(){var b=document.querySelector('.nav-toggle'),n=document.querySelector('.nav');if(b&&n)b.addEventListener('click',function(){n.classList.toggle('open');b.setAttribute('aria-expanded',n.classList.contains('open'));});document.querySelectorAll('[data-demo-form]').forEach(function(f){f.addEventListener('submit',function(e){e.preventDefault();var out=f.querySelector('.form-result');if(out){out.textContent='Демонстрационная форма: данные заполнены корректно. После размещения на CMS сообщения можно отправлять на e-mail.';out.className='form-result badge';}});});})();